import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.REACT_APP_SUPABASE_URL;
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseAnonKey) {
  throw new Error('Missing Supabase environment variables');
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true
  }
});

// Clean Authentication Service - NO VERIFICATION
export const authService = {
  async signUp(userData) {
    const { email, password, fullName, username, userType, company, bio } = userData;
    
    // Validate input data
    if (!email || !password || !fullName || !userType) {
      throw new Error('Missing required fields: email, password, fullName, and userType are required');
    }

    if (password.length < 6) {
      throw new Error('Password must be at least 6 characters long');
    }

    try {
      // Create auth user
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: email.toLowerCase().trim(),
        password,
        options: {
          data: {
            full_name: fullName,
            user_type: userType
          },
          emailRedirectTo: undefined
        }
      });

      if (authError) {
        console.error('Auth signup error:', authError);
        throw new Error(authError.message || 'Failed to create account');
      }
    } catch (error) {
      console.error('Signup error:', error);
      throw error;
    }

    // Create user profile
    if (authData.user) {
      const { data: profileData, error: profileError } = await supabase
        .from('users')
        .insert([
          {
            id: authData.user.id,
            email: email.toLowerCase(),
            full_name: fullName,
            username: username ? username.toLowerCase() : null,
            user_type: userType,
            bio: bio || null,
            company: company || null,
            // selected_plan: removed pricing feature
            status: 'active',
            rating: 0.00,
            tasks_completed: 0,
            tasks_created: 0,
            total_earnings: 0.00,
            wallet_balance: 0.00
          }
        ])
        .select()
        .single();

      if (profileError) {
        await supabase.auth.signOut();
        throw new Error('Failed to create user profile: ' + profileError.message);
      }

      return {
        user: authData.user,
        profile: profileData,
        session: authData.session
      };
    }

    throw new Error('Failed to create user account');
  },

  async signIn(email, password) {
    const { data, error } = await supabase.auth.signInWithPassword({
      email: email.toLowerCase(),
      password
    });

    if (error) {
      if (error.message.includes('Invalid login credentials')) {
        throw new Error('Invalid email or password');
      }
      throw error;
    }

    if (data.user) {
      const profile = await this.getProfile(data.user.id);
      return {
        user: data.user,
        profile,
        session: data.session
      };
    }

    return data;
  },

  async signOut() {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  },

  async getProfile(userId) {
    try {
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('id', userId)
        .maybeSingle(); // Use maybeSingle instead of single to handle no results gracefully

      if (error) {
        console.warn('Profile fetch failed:', error);
        // Return a basic profile structure instead of null
        return {
          id: userId,
          email: '',
          full_name: 'User',
          user_type: 'worker',
          created_at: new Date().toISOString()
        };
      }

      return data || {
        id: userId,
        email: '',
        full_name: 'User',
        user_type: 'worker',
        created_at: new Date().toISOString()
      };
    } catch (error) {
      console.error('Profile fetch error:', error);
      // Return fallback profile
      return {
        id: userId,
        email: '',
        full_name: 'User',
        user_type: 'worker',
        created_at: new Date().toISOString()
      };
    }
  },

  async getCurrentUser() {
    const { data: { user } } = await supabase.auth.getUser();
    
    if (!user) return { user: null, profile: null };

    const profile = await this.getProfile(user.id);
    return { user, profile };
  }
};

export default authService;
